B.Tn=new A.aX("ispat_11",B.cb,"Hukuki i\u015flemlerin miktar veya de\u011feri kanunda \xf6ng\xf6r\xfclen s\u0131n\u0131r\u0131 ge\xe7ti\u011fi takdirde kural olarak hangi delille ispat edilmesi zorunludur?",B.LW,1,"HMK m. 200 uyar\u0131nca, bir hakk\u0131n do\u011fumu, d\xfc\u015f\xfcr\xfclmesi, devri, de\u011fi\u015ftirilmesi, yenilenmesi, ertelenmesi, ikrar\u0131 ve itfas\u0131 amac\u0131yla yap\u0131lan hukuki i\u015flemlerin, yap\u0131ld\u0131klar\u0131 zamanki miktar veya de\u011ferleri kanunda \xf6ng\xf6r\xfclen s\u0131n\u0131r\u0131 ge\xe7ti\u011fi takdirde kural olarak senetle ispatlanmas\u0131 zorunludur.")
B.Lw=s(["Karde\u015fler aras\u0131ndaki hukuki i\u015flemler","E\u015fler aras\u0131ndaki hukuki i\u015flemler","Ortaklar aras\u0131ndaki ticari i\u015flemler","Altsoy ile \xfcstsoy aras\u0131ndaki hukuki i\u015flemler"],t.s)
B.TG=new A.aX("ispat_12",B.cb,"A\u015fa\u011f\u0131dakilerden hangisi, senetle ispat zorunlulu\u011fu olan bir hukuki i\u015flemin miktar ne olursa olsun tan\u0131kla ispat edilebilece\u011fi istisnai hallerden (delil ba\u015flang\u0131c\u0131 aranmaks\u0131z\u0131n) biri de\u011fildir?",B.Lw,2,"HMK m. 203 uyar\u0131nca altsoy-\xfcstsoy, karde\u015fler ve e\u015fler aras\u0131ndaki i\u015flemlerde miktar ne olursa olsun tan\u0131k dinlenebilir. Ortaklar aras\u0131ndaki i\u015flemler kural olarak bu istisnaya dahil edilmemi\u015ftir.")
